(function() {
  const ID5_PARTNER_ID = 1443;
  const DPI_MAP = {
    "adnxs": 1186917411, 
    "criteo": 687408927,
    "rubicon": 2086269774,
    "inmobi": 257925435, 
    "medianet": 1723987475, 
    "onetag": 445262707, 
    "openx": 1239766150,
    "pubmatic": 1402230080, 
    "richaudience": 1707625704, 
    "sharethrough": 1023151617, 
    "smartadserver": 1881119486, 
    "triplelift": 259151345,
    "ogury": 1629516480, 
    "blis": 1692986326,
    "ttd": 1633016725,
    "unruly": 1125232390,
    "yahooAds": 1028935272,
    "smaato": 1961916296
  };

  // --- Dynamic Utility Functions ---
  const isIiq = () => window.document.location.search.indexOf("iiq=1") > -1;
  const isGDPR = () => window.document.location.search.indexOf("gdpr=1") > -1;

  const getConsentString = () => {
    let match = window.document.location.search.match(/[^&]*&gdpr_consent=([^&]*)/);
    return (match && match.length > 1) ? match[1] : "";
  };

  const getIiqPartnerID = () => isGDPR() ? 95728119 : 1641699010;

  let id5LoadPromise = null;

  const generateGUID = () => {
    let d = new Date().getTime();
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
      const r = (d + Math.random() * 16) % 16 | 0;
      d = Math.floor(d / 16);
      return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
    });
  };

  // --- Pixel & Sync Triggers ---
  const callSetuid = (uidObj) => {
    const setuidURL = "https://a.bids.ws/setuid" + encodeURIComponent(JSON.stringify(uidObj));
    const img = window.document.createElement("img");
    img.src = setuidURL;
    window.document.body.appendChild(img);
  };

  const iiqGDPRSync = (uidObj) => {
    const imgURL = 'https://sync-gdpr.intentiq.com/profiles_engine/ProfilesEngineServlet' + getIiqPartnerID() + '&iiqidtype=2&iiqpcid=' + uidObj.pcid + '&iiqpciddate=' + uidObj.pcidDate + '&tsrnd=' + Date.now() + '&gdpr=1&gdpr_consent=' + getConsentString();
    const img = window.document.createElement("img");
    img.src = imgURL;
    window.document.body.appendChild(img);
  };

  const firePrimarySync = (uidObj) => {
    callSetuid(uidObj);
  };

  const runChromeSecondarySync = (uidObj) => {
    if (isIiq() && /Chrome|CriOS|Chromium/.test(navigator.userAgent)) {
      let cookieMatch = document.cookie.match(/uids=([^;]*)/);
      if (cookieMatch) {
        try {
          let json = JSON.parse(atob(cookieMatch[1]));
          let uids = json.tempUIDs || {};
          let syncUrl = "https://sync" + (isGDPR() ? "-gdpr" : "") + ".intentiq.com/profiles_engine/ProfilesEngineServlet?at=20&mi=10&dpi=" + getIiqPartnerID() + (isGDPR() ? "&gdpr=1&gdpr_consent=" + getConsentString() : "");
          let hasIds = false;

          for (const key in uids) {
            if (DPI_MAP[key]) {
              syncUrl += "&3rddpi=" + DPI_MAP[key] + "&3rdpcid=" + encodeURIComponent(uids[key].uid);
              hasIds = true;
            }
          }
          if (hasIds) {
            let img = window.document.createElement("img");
            img.src = syncUrl + '&iiqidtype=2&iiqpcid=' + uidObj.pcid + '&iiqpciddate=' + uidObj.pcidDate;
            window.document.body.appendChild(img);
          }
        } catch(e) { console.error("Chrome Sync Error", e); }
      }
    }
  };

  const runId5Sync = (uidObj) => {
    const baseSyncData = { ...uidObj };
    const id5Config = { partnerId: ID5_PARTNER_ID, allowLocalStorageWithoutConsentApi: true };
    if (isGDPR()) {
      id5Config.cmpApi = 'static';
      id5Config.consentData = { getTCData: { gdprApplies: true, tcString: getConsentString() } };
    }

    const executeId5Sync = () => {
      try {
        window.ID5.init(id5Config).onAvailable((status) => {
          let syncPayload = baseSyncData;
          let id5Eids;
          try {
            id5Eids = status && status.getUserIdsAsEids ? status.getUserIdsAsEids() : undefined;
          } catch (e) {
            id5Eids = undefined;
          }

          if (Array.isArray(id5Eids) && id5Eids.length > 0) {
            syncPayload = { ...baseSyncData, id5_eid: id5Eids };
            callSetuid(syncPayload);
          }

          runChromeSecondarySync(syncPayload);
        });
      } catch (e) {
        // Primary sync has already fired; ID5 init failures should not block delivery.
        runChromeSecondarySync(baseSyncData);
      }
    };

    if (window.ID5) {
      executeId5Sync();
      return;
    }

    if (!id5LoadPromise) {
      id5LoadPromise = new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = 'https://cdn.id5-sync.com/api/1.0/id5-api.js';
        script.onload = () => resolve();
        script.onerror = () => {
          id5LoadPromise = null;
          reject(new Error('ID5 script failed to load'));
        };
        document.head.appendChild(script);
      });
    }

    id5LoadPromise
      .then(() => {
        executeId5Sync();
      })
      .catch(() => {
        id5LoadPromise = null;
        runChromeSecondarySync(baseSyncData);
      });
  };

  const loadOrCreateFirstPartyData = () => {
    var FIRST_PARTY_KEY = '_iiq_fdata';
    let firstPartyData = null;

    try {firstPartyData = JSON.parse(window.localStorage.getItem(FIRST_PARTY_KEY)); } catch(e) {}
    if (!firstPartyData || !firstPartyData.pcid) {
      firstPartyData = { pcid: generateGUID(), pcidDate: Date.now() };
      try {window.localStorage.setItem(FIRST_PARTY_KEY, JSON.stringify(firstPartyData)); } catch (e) {}
    } else if (firstPartyData && !firstPartyData.pcidDate) {
      firstPartyData.pcidDate = Date.now();
      try {window.localStorage.setItem(FIRST_PARTY_KEY, JSON.stringify(firstPartyData));} catch (e) {}
    }

    return firstPartyData
  };

  window.iiqOnLoad = function() {
    let intentIq = (typeof IntentIqSyncObject !== 'undefined') ? new IntentIqSyncObject({ partner: getIiqPartnerID()}) : null;
    let uidObj = (intentIq && intentIq.firstPartyData) ? intentIq.firstPartyData : loadOrCreateFirstPartyData();
    firePrimarySync(uidObj);
    runId5Sync(uidObj);
  };

  const startSync = () => {
    const uidObj = loadOrCreateFirstPartyData();
    if (isIiq()) {
      if (isGDPR()) {
        iiqGDPRSync(uidObj);
        firePrimarySync(uidObj);
        runId5Sync(uidObj);
      } else {
        let script = document.createElement("script");
        script.src = 'https://agent.intentiq.com/Agent/GA/UniversalID-Sync/IIQUniversalID-sync.js';
        script.onload = window.iiqOnLoad;
        script.onerror = () => {
          firePrimarySync(uidObj);
          runId5Sync(uidObj);
        };
        document.head.appendChild(script);
      }
    } else {
      firePrimarySync(uidObj);
      runId5Sync(uidObj);
    }
  };

  startSync();
})();
